  await expect(page.getByRole("heading", { level: 1, name, exact: true })).toBeVisible();
  await expect(sheetTab(page, "Sheet1")).toHaveAttribute("aria-selected", "true");
  await expect(cell(page, "A1")).toHaveText("ok");
});

